export class WenetEngine {
  constructor(modelPath) {
    this.modelPath = modelPath;
    this.session = null;
  }

  async init() {
    let ort;
    try {
      ort = await import("onnxruntime-node");
    } catch (err) {
      throw new Error(
        "onnxruntime-node is not installed. Run `npm install` inside js/duix-sdk. " + err.message,
      );
    }
    this.session = await ort.InferenceSession.create(this.modelPath, {
      executionProviders: ["cpu"],
      intraOpNumThreads: 2,
      interOpNumThreads: 1,
      graphOptimizationLevel: "all",
    });
  }

  /**
   * @param {Float32Array} mel frame-major [melcnt, 80]
   * @returns {Promise<Float32Array>} [bnfcnt, 256] flattened
   */
  async run(mel, melcnt, bnfcnt) {
    const ort = await import("onnxruntime-node");
    const used = Math.min(melcnt * 80, mel.length);
    const speech = new Float32Array(melcnt * 80);
    speech.set(mel.subarray(0, used));
    const speechTensor = new ort.Tensor("float32", speech, [1, melcnt, 80]);
    const lenTensor = new ort.Tensor("int32", Int32Array.from([melcnt]), [1]);
    const out = await this.session.run({
      speech: speechTensor,
      speech_lengths: lenTensor,
    });
    const encoder = out.encoder_out;
    const flat = encoder.data;
    const need = bnfcnt * 256;
    const bnf = new Float32Array(need);
    bnf.set(flat.subarray(0, Math.min(need, flat.length)));
    return bnf;
  }
}
